// Map shapes: a tile from civ-core's starting map, and a tile as the map board draws it.

import type { CivIndex, ResourceKind, UnitKind } from "./game";

/** One tile of the starting map, as generated by civ-core. */
export type MapTile = {
  x: number;
  y: number;
  owner: CivIndex | null;
  deposit: ResourceKind | null;
  isCity: boolean;
  /** A city may be built here (capitals start on one). */
  isCitySite: boolean;
};

/** A tile as the map board draws it at some turn. */
export type BoardTile = MapTile & {
  /** Two civs reach this tile at nearly the same time. */
  isContested: boolean;
  unit: UnitKind | null;
  /** Whose unit it is (an army on the march can stand on another civ's land). */
  unitCiv: CivIndex | null;
};

/** A board at one turn, plus how many tiles each civ owns. */
export type BoardState = {
  tiles: BoardTile[];
  tilesByCiv: Record<CivIndex, number>;
};

/** One civ's numbers at one moment of a simulated match. */
export type SimulatedCiv = {
  isAlive: boolean;
  tiles: number;
  cities: number;
  /** Fighting units. */
  army: number;
  food: number;
  ore: number;
  gold: number;
  coins: number;
  /** Coins plus resources at that moment's market prices. */
  wealth: number;
  /** Fighting units on the march (0 if none). */
  marching: number;
  /** Where the civ's army is marching, or null (docs/decisions/0010). */
  armyAt: { x: number; y: number } | null;
};

/** A whole match simulated in the browser by civ-core (the same rules as the chain). */
export type SimulationResult = {
  /** `turns[0]` is the start; `turns[t]` is after t turns. */
  turns: { tiles: MapTile[]; civs: SimulatedCiv[] }[];
  /** How many turns each of civ 0's rules acted, rule 1 first. */
  yourRuleCounts: number[];
  /** The final state's fingerprint (the same number the chain would reach). */
  fingerprint: string;
};
